corpus_block("test-labels.R: position axis label hierarchy works as intended", {
  df <- data_frame(foo = c(1e1, 1e5), bar = c(0, 100))
  .plot("test-labels.R: position axis label hierarchy works as intended #1", p <- ggplot(df, aes(foo, bar)) +
      geom_point(size = 5))
  p <- ggplot_build(p)
  resolve_label <- function(x) p@layout$resolve_label(x, p@plot@labels)
  xsec <- scale_x_continuous("Baz", sec.axis = dup_axis(name = "grault"))
  ysec <- scale_y_continuous("Qux", sec.axis = dup_axis(name = "garply"))
  ysec <- scale_y_continuous("Qux", sec.axis = dup_axis(name = "garply"))
})

corpus_block("test-labels.R: labels can be derived using functions", {
  .plot("test-labels.R: labels can be derived using functions #1", p <- ggplot(mtcars, aes(disp, mpg, colour = drat, shape = factor(cyl))) +
      geom_point() +
      labs(
